const ALLOWED_ACCOUNT_TYPES = ['SANDBOX', 'DEVELOPER_TEST'];
const STORAGE_TARGET_VALUES = ['s3', 'sheets', 'file'];
const N8N_STORAGE_TARGETS = ['s3', 'sheets'];
const RETENTION_MIN_DAYS = 30;
