    const v = verifications ? verifications[t] : null;
    if (!v) failed.push(t + ': not executed');
    else if (!v.ok) failed.push(t + ': ' + (v.reason || 'failed'));
    else if (v.runId !== backup.runId) failed.push(t + ': verification belongs to a different run');
